using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using OCRS.Data; using OCRS.Models.Enums; using OCRS.ViewModels.Dashboard;
namespace OCRS.Areas.Admin.Controllers;
[Area("Admin"),Authorize(Roles="Admin")] public class DashboardController(ApplicationDbContext db):Controller { public async Task<IActionResult> Index(){var m=new DashboardViewModel{Students=await db.Students.CountAsync(),Instructors=await db.Instructors.CountAsync(),Courses=await db.Courses.CountAsync(),Classes=await db.CourseClasses.CountAsync(),Enrollments=await db.Enrollments.CountAsync(),OpenClasses=await db.CourseClasses.CountAsync(x=>x.Status==ClassStatus.OpenForRegistration),FullClasses=await db.CourseClasses.CountAsync(x=>x.CurrentEnrollment>=x.MaxCapacity),RecentEnrollments=await db.Enrollments.Include(x=>x.Student).ThenInclude(x=>x.User).Include(x=>x.Class).OrderByDescending(x=>x.RegisteredAt).Take(8).ToListAsync()};var cap=await db.CourseClasses.SumAsync(x=>(int?)x.MaxCapacity)??0;var used=await db.CourseClasses.SumAsync(x=>(int?)x.CurrentEnrollment)??0;m.FillRate=cap==0?0:Math.Round(used*100d/cap,1);var start=new DateTime(DateTime.UtcNow.Year,DateTime.UtcNow.Month,1).AddMonths(-5);var stats=await db.Enrollments.Where(x=>x.RegisteredAt>=start).GroupBy(x=>new{x.RegisteredAt.Year,x.RegisteredAt.Month}).Select(g=>new{g.Key.Year,g.Key.Month,Count=g.Count()}).ToListAsync();for(var i=0;i<6;i++){var d=start.AddMonths(i);m.MonthLabels.Add(d.ToString("MM/yyyy"));m.MonthValues.Add(stats.FirstOrDefault(x=>x.Year==d.Year&&x.Month==d.Month)?.Count??0);}return View(m);} }
